trigger_evidence:
this.createError({
              message: "Vending evidence required",
            })

this.createError({
              message: "Final switch-on evidence required",
            })

this.createError({
              message: "Keypad issued evidence required",
            })

this.createError({
              message: "Water operational evidence required",
            })

this.createError({
              message: "Water reading / flow evidence required",
            })

{
              success: false,
              code: "NAv",
              message: "NAv",
              trnId: "NAv",
            }

buildFailureResult(
        "INVALID_COMMISSIONING_TRN_TYPE",
        "Only METER_COMMISSIONING is supported by this callable",
        {
          trnId,
          trnType,
          astId,
        },
      )

buildFailureResult(
          "AST_NOT_FOUND",
          "The referenced AST does not exist",
          {
            trnId,
            trnType,
            astId,
            premiseId,
          },
        )

buildFailureResult(
          "PREMISE_NOT_FOUND",
          "The referenced premise does not exist",
          {
            trnId,
            trnType,
            astId,
            premiseId,
          },
        )

buildFailureResult(
          commissioningCheck?.code,
          commissioningCheck?.message,
          {
            trnId,
            trnType,
            astId,
            premiseId,
          },
        )

buildFailureResult("UNKNOWN_ERROR", "Commissioning TRN was not created", {
        trnId,
        trnType,
        astId,
        premiseId,
      })

{
      ok: false,
      code: "INVALID_COMMISSIONING_ANSWER",
      message: `${fieldLabel} must be answered yes or no`,
    }

{
      ok: false,
      code: "COMMISSIONING_NOTES_REQUIRED",
      message: `Notes are required when ${fieldLabel} is no`,
    }

{
      ok: false,
      code: "COMMISSIONING_EVIDENCE_REQUIRED",
      message: `${evidenceLabel || fieldLabel} evidence is required`,
    }

{
      ok: false,
      code: "INVALID_TRN_ID",
      message: "Commissioning TRN id is required",
    }

{
      ok: false,
      code: "INVALID_COMMISSIONING_TRN_ID",
      message: `Commissioning TRN id must start with ${COMMISSIONING_TRN_PREFIX}`,
    }

{
      ok: false,
      code: "INVALID_ACCESS_DATA",
      message: "accessData is required",
    }

{
      ok: false,
      code: "INVALID_COMMISSIONING_TRN_TYPE",
      message: "accessData.trnType must be METER_COMMISSIONING",
    }

{
      ok: false,
      code: "INVALID_AST_ID",
      message: "ast.astData.astId is required",
    }

{
      ok: false,
      code: "INVALID_PREMISE_ID",
      message: "A valid premise id is required",
    }

{
      ok: false,
      code: "INVALID_COMMISSIONING_DATA",
      message: "commissioning answers are required",
    }

{
            trnId,
            astId,
            code: commissioningCheck?.code,
            message: commissioningCheck?.message,
          }

{
            trnId,
            astId,
            code: astPatchResult.code,
            message: astPatchResult.message,
          }

{
        success: false,
        code: "NAv",
        message: "NAv",
        trnId: "NAv",
      }

{
        success: true,
        code: result?.code || "SUCCESS",
        message: result?.message || "Synced successfully",
        trnId: result?.trnId || "NAv",
      }
